import java.util.Scanner;

public class Main {
    static final int MAX_LIMIT = 1000005;
    static final int MOD_VAL = 1000000007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p_value_input = sc.nextInt();
        int k_value_input = sc.nextInt();

        if (k_value_input == 0) {
            long total_product = 1;
            for (int i = 1; i < p_value_input; ++i) {
                total_product = (total_product * p_value_input) % MOD_VAL;
            }
            System.out.println(total_product);
            sc.close();
            return;
        }

        int[] sequence_array = new int[p_value_input];
        boolean[] visited_array = new boolean[p_value_input];

        for (int i = 1; i < p_value_input; ++i) {
            sequence_array[i] = (int)((long)k_value_input * i % p_value_input);
        }

        long final_ans = 1;

        for (int start_idx = 0; start_idx < p_value_input; ++start_idx) {
            if (!visited_array[start_idx]) {
                int cycle_length = 0;
                int current_idx = start_idx;
                int product_mod = 1;

                while (!visited_array[current_idx]) {
                    visited_array[current_idx] = true;
                    current_idx = sequence_array[current_idx];
                    cycle_length++;
                    product_mod = (int)((long)product_mod * k_value_input % p_value_input);
                }

                if (cycle_length == 1) {
                    int factor = (k_value_input == 1) ? p_value_input : 1;
                    final_ans = (final_ans * factor) % MOD_VAL;
                } else {
                    assert product_mod == 1;
                    final_ans = (final_ans * p_value_input) % MOD_VAL;
                }
            }
        }

        System.out.println(final_ans);
        sc.close();
    }
}
